import { GitViseError, type JsonValue, type SwarmFlowSpec, type SwarmTaskSpec } from '@gitvise/core';

/**
 * Tenant isolation for shared infrastructure. Repos, flows, worktrees, and memory namespaces live in global
 * stores (D1, Durable Objects, Vectorize), so each caller-supplied id is prefixed with the caller's org id before
 * it reaches them. An org can name its own repo `api`, but it cannot name another org's `api`, because that
 * name is stored as `<org>:api`. Org ids are generated by the gateway and never contain `:`.
 */

const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
/** Keeps the scoped id, `org-` plus 16 hex plus `:` plus this, under the 128-character limit in the core validation. */
const MAX_CLIENT_ID_LENGTH = 80;

export function scopeId(orgId: string, id: unknown, field = 'id'): string {
  if (typeof id !== 'string' || !ID_PATTERN.test(id) || id.length > MAX_CLIENT_ID_LENGTH) {
    throw new GitViseError('INVALID_REQUEST', `${field} must be an identifier of at most ${MAX_CLIENT_ID_LENGTH} characters`);
  }
  return `${orgId}:${id}`;
}

/** Removes the org prefix from a stored id. Ids that do not carry the prefix are returned unchanged. */
export function unscopeId(orgId: string, stored: string): string {
  const prefix = `${orgId}:`;
  return stored.startsWith(prefix) ? stored.slice(prefix.length) : stored;
}

/**
 * Re-keys a flow for one org. Every task's input is overwritten with the caller's org and the scoped repo.
 * Any `orgId` or `repoId` the caller sent is discarded, because the handlers bill and act on these fields.
 */
export function scopeFlowSpec(orgId: string, body: unknown): SwarmFlowSpec {
  if (typeof body !== 'object' || body === null) throw new GitViseError('INVALID_REQUEST', 'body must be a JSON object');
  const spec = body as { flowId?: unknown; repoId?: unknown; tasks?: unknown; specHash?: unknown };
  if (!Array.isArray(spec.tasks)) throw new GitViseError('INVALID_REQUEST', 'tasks must be an array');
  const repoId = scopeId(orgId, spec.repoId, 'repoId');

  const tasks: SwarmTaskSpec[] = spec.tasks.map((entry: unknown) => {
    if (typeof entry !== 'object' || entry === null) throw new GitViseError('INVALID_REQUEST', 'each task must be an object');
    const task = entry as { taskId?: unknown; queue?: unknown; dependsOn?: unknown; input?: unknown };
    if (typeof task.input !== 'object' || task.input === null || Array.isArray(task.input)) {
      throw new GitViseError('INVALID_REQUEST', 'task input must be an object');
    }
    const input: Record<string, JsonValue> = {
      ...(task.input as Record<string, JsonValue>),
      orgId,
      repoId,
    };
    return {
      taskId: task.taskId as string,
      queue: task.queue as string,
      dependsOn: (task.dependsOn ?? []) as string[],
      input,
    };
  });

  return {
    flowId: scopeId(orgId, spec.flowId, 'flowId'),
    repoId,
    tasks,
    ...(typeof spec.specHash === 'string' ? { specHash: spec.specHash } : {}),
  };
}

/** Records which org created a sandbox lease. Lease ids are random, but ownership is still checked on every use. */
export async function recordLeaseOwner(db: D1Database, leaseId: string, orgId: string): Promise<void> {
  await db.prepare('INSERT INTO sandbox_leases (lease_id, org_id) VALUES (?1, ?2)').bind(leaseId, orgId).run();
}

/** Throws NOT_FOUND for another org's lease. It says nothing about the lease's existence, so ids cannot be probed. */
export async function assertLeaseOwner(db: D1Database, leaseId: string, orgId: string): Promise<void> {
  const row = await db
    .prepare('SELECT org_id FROM sandbox_leases WHERE lease_id = ?1')
    .bind(leaseId)
    .first<{ org_id: string }>();
  if (row === null || row.org_id !== orgId) throw new GitViseError('NOT_FOUND', 'sandbox lease not found');
}

export async function forgetLease(db: D1Database, leaseId: string): Promise<void> {
  await db.prepare('DELETE FROM sandbox_leases WHERE lease_id = ?1').bind(leaseId).run();
}
